from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    store = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        if key not in store:
            return True
        _, wt = store[key]
        return t >= wt + ttl

    for op in ops:
        kind = op[0]
        t = op[1]
        if kind == 'put':
            key = op[2]
            value = op[3]
            if key in store:
                if not is_expired(key, t):
                    del store[key]
                else:
                    del store[key]
            else:
                if len(store) >= capacity:
                    # need to check for expired entries first? evict LRU regardless
                    # remove expired entries doesn't matter for eviction count per spec,
                    # but expired entries count as absent for every purpose, so they
                    # shouldn't count toward capacity.
                    # Clean expired entries
                    expired_keys = [k for k, (_, wt) in store.items() if t >= wt + ttl]
                    for ek in expired_keys:
                        del store[ek]
                    if len(store) >= capacity:
                        # evict LRU (first item)
                        store.popitem(last=False)
            store[key] = (value, t)
            store.move_to_end(key)
        elif kind == 'get':
            key = op[2]
            if key in store and not is_expired(key, t):
                value, wt = store[key]
                store.move_to_end(key)
                results.append(value)
            else:
                if key in store:
                    del store[key]
                results.append(-1)

    return results

